:"S22B-C05","clave":"s22b_legacy_464","familia":"MFA_OTP_SSO","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"B2B","modo":"HEREDA","dueno":"TECNICO","titulo":"Destinos legales y soporte del login B2B","descripcion":"En Login B2B BLOQUEAR ocultar accesos a Términos y Condiciones, Política de Privacidad o Soporte, o resolverlos a rutas no canónicas B2B, protegidas por sesión, reutilizadas automáticamente del frente B2C o URLs externas hardcodeadas. Binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/464","solicitante":"Cristhian / Claude S22-B 2026-11-24"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22b05_login_b2b"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22b05_accesos_visibles"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"s22b05_rutas_b2b_canonicas"},"der":{"lit":false}}},"der":{"op":"=","izq":{"hecho":"s22b05_acceso_sin_sesion"},"der":{"lit":false}}},"der":{"op":"=","izq":{"hecho":"s22b05_reuso_b2c_o_url_fija"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22b05_login_b2b":true,"s22b05_accesos_visibles":true,"s22b05_rutas_b2b_canonicas":true,"s22b05_acceso_sin_sesion":true,"s22b05_reuso_b2c_o_url_fija":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22b05_login_b2b":true,"s22b05_accesos_visibles":false,"s22b05_rutas_b2b_canonicas":true,"s22b05_acceso_sin_sesion":true,"s22b05_reuso_b2c_o_url_fija":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22b05_login_b2b":true,"s22b05_accesos_visibles":true,"s22b05_rutas_b2b_canonicas":false,"s22b05_acceso_sin_sesion":true,"s22b05_reuso_b2c_o_url_fija":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22b05_login_b2b":true,"s22b05_accesos_visibles":true,"s22b05_rutas_b2b_canonicas":true,"s22b05_acceso_sin_sesion":false,"s22b05_reuso_b2c_o_url_fija":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22b05_login_b2b":true,"s22b05_accesos_visibles":true,"s22b05_rutas_b2b_canonicas":true,"s22b05_acceso_sin_sesion":true,"s22b05_reuso_b2c_o_url_fija":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22b05_login_b2b":false,"s22b05_accesos_visibles":false,"s22b05_rutas_b2b_canonicas":false,"s22b05_acceso_sin_sesion":false,"s22b05_reuso_b2c_o_url_fija":true},"esperado":false}]},"hash":"82a67a7beddff384f623c0c70a333133641a30c0d82d17b78416709aac28bc8f","hash_paquete":"f6f1f80cbba4a27b64bdefb5abd859c0c62e1e2063ed3bdb7fd7c5975bfef734","hash_evaluado":"82a67a7bed","hash_paquete_10":"f6f1f80cbb","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22B-C06","legacy_id":506,"legacy_ids":[506],"relacionadas":[],"residual":"","coberturas":[{"legacy_id":506,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"En recepción server-side de webhook de entrega OTP Brevo BLOQUEAR aceptar o persistir eventos o modificar estado funcional sin HTTPS y Bearer válido. IP oficial es defensa secundaria, no sustituye autenticación. BLOQUEAR persistir el secreto en lf_ops. Binding pendiente."}],"hechos":["s22b06_webhook_brevo","s22b06_https","s22b06_bearer_valido","s22b06_acepta_o_persiste_o_modifica","s22b06_secreto_persistido"],"paquete":{"tipo":"NUEVA","codigo":"S22B-C06","clave":"s22b_legacy_506","familia":"MFA_OTP_SSO","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"B2B","modo":"HEREDA","dueno":"TECNICO","titulo":"Autenticación de eventos OTP de Brevo","descripcion":"En recepción server-side de webhook de entrega OTP Brevo BLOQUEAR aceptar o persistir eventos o modificar estado funcional sin HTTPS y Bearer válido. IP oficial es defensa secundaria, no sustituye autenticación. BLOQUEAR persistir el secreto en lf_ops. Binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/506","solicitante":"Cristhian / Claude S22-B 2026-11-24"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22b06_webhook_brevo"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"y","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22b06_https"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"s22b06_bearer_valido"},"der":{"lit":false}}},"der":{"op":"=","izq":{"hecho":"s22b06_acepta_o_persiste_o_modifica"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22b06_secreto_persistido"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22b06_webhook_brevo":true,"s22b06_https":true,"s22b06_bearer_valido":true,"s22b06_acepta_o_persiste_o_modifica":true,"s22b06_secreto_persistido":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22b06_webhook_brevo":true,"s22b06_https":false,"s22b06_bearer_valido":true,"s22b06_acepta_o_persiste_o_modifica":true,"s22b06_secreto_persistido":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22b06_webhook_brevo":true,"s22b06_https":true,"s22b06_bearer_valido":false,"s22b06_acepta_o_persiste_o_modifica":true,"s22b06_secreto_persistido":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22b06_webhook_brevo":true,"s22b06_https":true,"s22b06_bearer_valido":false,"s22b06_acepta_o_persiste_o_modifica":false,"s22b06_secreto_persistido":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22b06_webhook_brevo":true,"s22b06_https":true,"s22b06_bearer_valido":true,"s22b06_acepta_o_persiste_o_modifica":false,"s22b06_secreto_persistido":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22b06_webhook_brevo":false,"s22b06_https":false,"s22b06_bearer_valido":false,"s22b06_acepta_o_persiste_o_modifica":true,"s22b06_secreto_persistido":true},"esperado":false}]},"hash":"2e46ac683e2075c2b88d17b9fa5f94bbd97108cbc35eea5210e418874557b61e","hash_paquete":"adbf1767f0076ac1ebcd36a1155572bf27799eaa7a85b7f98b5ecf384dddeb3d","hash_evaluado":"2e46ac683e","hash_paquete_10":"adbf1767f0","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"Adyacente a S1-C03/S5-C16; Brevo eventos de entrega es distinto."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','PR #4757 / Claude 2026-11-24 22:51 Lima / '||cd||' / hash_paquete_10='||(p->>'hash_paquete_10'));
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22B_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22B_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22B_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>5 OR vectors<>28 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22B_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR (c->>'estado_cobertura'='PARCIAL' AND length(residual)<15) OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') THEN RAISE EXCEPTION 'S22B_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,1,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-24 22:51 Lima'),h,'GPT / Claude S22-B independiente');
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22B_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 direct_hash:=lf_ops.nucleo_hash_paquete_v1('S6-C13',1);
 IF direct_hash IS NULL OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla='S6-C13' AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22B_DIRECT_ATTESTATION_MISSING'; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=315) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=315;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla='S6-C13' AND version=1;
 diff:='S6-C13 conserva captura en iframe SDK Niubiz y bloqueo de PAN/CVV en servidores LF; no explicita nombre del titular ni prohibición de formulario fuera del iframe.'; residual:='El nombre del titular y la restricción de formulario fuera del iframe no están explícitos en S6-C13.';
 IF length(diff)<30 OR length(residual)<15 THEN RAISE EXCEPTION 'S22B_DIRECT_CONTRACT'; END IF;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(315,'S6-C13',1,'PARCIAL',diff,jsonb_build_object('fuente','lf_ops.reglas/315','contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-24 22:51 Lima'),direct_hash,'GPT / Claude S22-B independiente');
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22B_SOURCE_MISSING 315'; END IF;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>8 OR after_replaced<>before_replaced+5) THEN RAISE EXCEPTION 'S22B_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22B_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22B_PASS 5 JUICIOS 5 AUTO 28 VECTORES links=% replaced=% DPIG03=0',links,after_replaced;
END $s22$;
COMMIT;
